// js/supabase-client.js
// Single shared Supabase client, built from window.APP_CONFIG
// (generated by scripts/generate-config.js — see README).

export function getSupabaseClient() {
  if (window.__sb) return window.__sb;
  const cfg = window.APP_CONFIG || {};
  if (!cfg.SUPABASE_URL || cfg.SUPABASE_URL.includes('your-project-ref')) {
    console.error('APP_CONFIG is not set. Run `npm run build:config` or fill js/config.js.');
  }
  window.__sb = supabase.createClient(cfg.SUPABASE_URL, cfg.SUPABASE_ANON_KEY, {
    auth: { persistSession: true, autoRefreshToken: true }
  });
  return window.__sb;
}

export const AUTHORIZED_EMAIL = (window.APP_CONFIG && window.APP_CONFIG.AUTHORIZED_EMAIL) || null;
